// ===== SECURE REST API IMPLEMENTATION =====
// Node.js + Express with security best practices

const express = require('express');
const helmet = require('helmet');          // Security headers
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const cors = require('cors');

const app = express();

// ===== 1. SECURITY HEADERS =====
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
    directives: {
        defaultSrc: ["'self'"],
        scriptSrc: ["'self'", "'strict-dynamic'"],
        styleSrc: ["'self'", "'unsafe-inline'"],
        imgSrc: ["'self'", "data:", "https://trusted-cdn.com"],
        connectSrc: ["'self'"],
        frameAncestors: ["'none'"],
        formAction: ["'self'"],
        upgradeInsecureRequests: []
    }
}));

// ===== 2. CORS (be specific, don't use '*') =====
app.use(cors({
    origin: ['https://app.example.com', 'https://admin.example.com'],
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    credentials: true,
    maxAge: 86400  // Preflight cache for 24 hours
}));

// ===== 3. RATE LIMITING =====
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000,  // 15 minutes
    max: 100,                    // limit each IP to 100 requests per windowMs
    message: { error: 'Too many requests, please try again later.' },
    standardHeaders: true,
    legacyHeaders: false,
    keyGenerator: (req) => {
        // Use combination of IP and user ID for more granular limits
        return req.user ? `${req.ip}-${req.user.id}` : req.ip;
    }
});
app.use('/api/', limiter);

// Stricter limit for auth endpoints
const authLimiter = rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 5,  // 5 login attempts per 15 minutes
    message: { error: 'Too many login attempts. Account locked for 15 minutes.' }
});
app.use('/api/auth/login', authLimiter);

// ===== 4. INPUT VALIDATION =====
app.post('/api/users',
    body('email').isEmail().normalizeEmail(),
    body('username').isAlphanumeric().isLength({ min: 3, max: 30 }),
    body('password').isLength({ min: 12 }).matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/),
    (req, res) => {
        const errors = validationResult(req);
        if (!errors.isEmpty()) {
            return res.status(400).json({ errors: errors.array() });
        }
        // Process valid request...
    }
);

// ===== 5. SECURE JWT AUTHENTICATION =====
const JWT_SECRET = process.env.JWT_SECRET;  // NEVER hardcode!
const JWT_ALGORITHM = 'RS256';  // Use asymmetric, NOT 'none' or 'HS256'

function generateTokens(user) {
    const accessToken = jwt.sign(
        { userId: user.id, role: user.role, permissions: user.permissions },
        JWT_SECRET,
        { algorithm: JWT_ALGORITHM, expiresIn: '15m', issuer: 'myapp' }
    );

    const refreshToken = jwt.sign(
        { userId: user.id, tokenVersion: user.tokenVersion },
        JWT_SECRET,
        { algorithm: JWT_ALGORITHM, expiresIn: '7d' }
    );

    return { accessToken, refreshToken };
}

// ===== 6. AUTHORIZATION MIDDLEWARE =====
function authenticate(req, res, next) {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
        return res.status(401).json({ error: 'No token provided' });
    }

    const token = authHeader.split(' ')[1];
    try {
        const decoded = jwt.verify(token, JWT_SECRET, {
            algorithms: [JWT_ALGORITHM],
            issuer: 'myapp'
        });
        req.user = decoded;
        next();
    } catch (err) {
        if (err.name === 'TokenExpiredError') {
            return res.status(401).json({ error: 'Token expired', code: 'TOKEN_EXPIRED' });
        }
        return res.status(401).json({ error: 'Invalid token' });
    }
}

function authorize(...roles) {
    return (req, res, next) => {
        if (!roles.includes(req.user.role)) {
            return res.status(403).json({ error: 'Insufficient permissions' });
        }
        next();
    };
}

// ===== 7. PROTECTED ROUTES =====
app.get('/api/users/:id', authenticate, (req, res) => {
    // IDOR prevention: Check that user can only access their own data
    // (unless they're admin)
    if (req.params.id !== req.user.userId && req.user.role !== 'admin') {
        return res.status(403).json({ error: 'Access denied' });
    }
    // Continue with authorized request...
});

app.delete('/api/users/:id', authenticate, authorize('admin'), (req, res) => {
    // Only admins can delete users
});

// ===== 8. SECURE ERROR HANDLING =====
app.use((err, req, res, next) => {
    console.error(err.stack);  // Log internally
    res.status(err.status || 500).json({
        error: process.env.NODE_ENV === 'production'
            ? 'Internal server error'
            : err.message  // Never expose this in production!
    });
});

