const https = require('https');
const fs = require('fs');

const options = {
    key: fs.readFileSync('/etc/ssl/private/key.pem'),
    cert: fs.readFileSync('/etc/ssl/certs/cert.pem'),
    // Modern TLS settings
    secureOptions: constants.SSL_OP_NO_TLSv1 | constants.SSL_OP_NO_TLSv1_1,
    ciphers: [
        'TLS_AES_256_GCM_SHA384',
        'TLS_CHACHA20_POLY1305_SHA256',
        'TLS_AES_128_GCM_SHA256'
    ].join(':'),
    honorCipherOrder: true
};

https.createServer(options, app).listen(443);

// ===== WEBAUTHN: PASSWORDLESS AUTHENTICATION =====
// Implementation uses public key cryptography
// Private key NEVER leaves the user's device

"""
HOW WEBAUTHN WORKS:
1. Registration: User's device generates a public/private key pair
   - Private key stays on device (in TPM or Secure Enclave)
   - Public key is sent to the server
2. Authentication: Server sends a challenge, device signs it with private key
   - Server verifies signature with public key
   - No password to leak, no phishing possible (domain-bound)
"""

// ===== REGISTRATION (Client-side JavaScript) =====
const register = async () => {
    const publicKeyCredentialCreationOptions = {
        challenge: new Uint8Array(32),  // Server-generated random challenge
        rp: {
            name: "My Application",
            id: "example.com"  // Must match origin domain!
        },
        user: {
            id: new Uint8Array(16),  // Server-generated user ID
            name: "user@example.com",
            displayName: "John Doe"
        },
        pubKeyCredParams: [
            { type: "public-key", alg: -7 },   // ES256
            { type: "public-key", alg: -257 },  // RS256
        ],
        authenticatorSelection: {
            authenticatorAttachment: "platform",  // Use built-in (fingerprint)
            // Or "cross-platform" for USB keys
            residentKey: "preferred",  // Discoverable credential
            userVerification: "required"  // Always verify (PIN/fingerprint)
        },
        timeout: 60000,
        attestation: "direct"
    };

    try {
        const credential = await navigator.credentials.create({
            publicKey: publicKeyCredentialCreationOptions
        });

        // Send credential to server for verification
        const credentialData = {
            id: credential.id,
            rawId: new Uint8Array(credential.rawId),
            type: credential.type,
            response: {
                clientDataJSON: new Uint8Array(credential.response.clientDataJSON),
                attestationObject: new Uint8Array(credential.response.attestationObject)
            }
        };

        await fetch('/api/webauthn/register', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(credentialData)
        });

        console.log('Registration successful!');
    } catch (err) {
        console.error('Registration failed:', err);
    }
};

// ===== AUTHENTICATION (Login) =====
const login = async () => {
    // Get challenge from server
    const challengeResponse = await fetch('/api/webauthn/login/start');
    const challenge = await challengeResponse.json();

    const publicKeyCredentialRequestOptions = {
        challenge: new Uint8Array(challenge.challenge),
        timeout: 60000,
        userVerification: "required"
    };

    try {
        const assertion = await navigator.credentials.get({
            publicKey: publicKeyCredentialRequestOptions
        });

        // Send assertion to server
        const assertionData = {
            id: assertion.id,
            rawId: new Uint8Array(assertion.rawId),
            type: assertion.type,
            response: {
                clientDataJSON: new Uint8Array(assertion.response.clientDataJSON),
                authenticatorData: new Uint8Array(assertion.response.authenticatorData),
                signature: new Uint8Array(assertion.response.signature),
                userHandle: assertion.response.userHandle
                    ? new Uint8Array(assertion.response.userHandle)
                    : null
            }
        };

        const result = await fetch('/api/webauthn/login/finish', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(assertionData)
        });

        if (result.ok) {
            console.log('Login successful!');
        }
    } catch (err) {
        console.error('Login failed:', err);
    }
};
